(function(root){'use strict';
const SCHEMA=1;
function fresh(){return {schema:SCHEMA,read:{},checks:{},notes:{},review:{},selectedTrack:'',theme:'dark'};}
function plain(x){return x!==null&&typeof x==='object'&&!Array.isArray(x)&&Object.getPrototypeOf(x)===Object.prototype;}
function validateProgress(x,ids){if(!plain(x)||x.schema!==SCHEMA)throw Error('Unsupported progress format.');const out=fresh();for(const key of ['read','checks','notes','review']){if(!plain(x[key]))throw Error('Invalid '+key+' data.');for(const [id,value]of Object.entries(x[key])){if(!ids.includes(id))continue;if(key==='notes'){if(typeof value!=='string'||value.length>10000)throw Error('Invalid note.');out.notes[id]=value;}else if(key==='review'){if(!plain(value)||!Number.isInteger(value.streak)||value.streak<0||value.streak>50||!Number.isFinite(value.due)||value.due<0||value.due>8640000000000000)throw Error('Invalid review record.');out.review[id]={streak:value.streak,due:value.due};}else{if(typeof value!=='boolean')throw Error('Invalid completion value.');out[key][id]=value;}}}if(typeof x.selectedTrack==='string')out.selectedTrack=x.selectedTrack.slice(0,100);out.theme=x.theme==='light'?'light':'dark';return out;}
// Discovery only: normalize comparison keys, never stored text or identity.
function matchesSearch(text,query){const normalize=value=>String(value).normalize('NFKC').toLowerCase().normalize('NFKC'),haystack=normalize(text),terms=normalize(query).trim().split(/\s+/u).filter(Boolean);return terms.every(term=>haystack.includes(term));}
function grade(state,id,correct,now){const next=JSON.parse(JSON.stringify(state));const prior=next.review[id]||{streak:0,due:0};const streak=correct?Math.min(prior.streak+1,50):0;const days=correct?[1,3,7,14,30][Math.min(streak-1,4)]:0;next.review[id]={streak,due:now+(correct?days*86400000:10*60000)};next.checks[id]=correct;return next;}
function ipToNumber(ip){if(typeof ip!=='string'||!/^\d{1,3}(\.\d{1,3}){3}$/.test(ip))throw Error('Enter four decimal IPv4 octets.');const p=ip.split('.').map(Number);if(p.some(n=>n<0||n>255))throw Error('Each octet must be 0–255.');return p.reduce((a,n)=>a*256+n,0);}
function numberToIp(n){return [24,16,8,0].map(s=>Math.floor(n/2**s)%256).join('.');}
function subnet(ip,prefix){if(!Number.isInteger(prefix)||prefix<1||prefix>30)throw Error('This teaching tool supports /1 through /30. /31 and /32 have special semantics.');const n=ipToNumber(ip);const size=2**(32-prefix),network=Math.floor(n/size)*size,broadcast=network+size-1;return {network:numberToIp(network),broadcast:numberToIp(broadcast),first:numberToIp(network+1),last:numberToIp(broadcast-1),hosts:size-2,mask:numberToIp(2**32-size),size};}
function policy({authenticated,allow,deny}){if(!authenticated)return {decision:'Deny',reason:'No authenticated identity in this simplified model.'};if(deny)return {decision:'Deny',reason:'An applicable explicit deny overrides the allow.'};if(allow)return {decision:'Allow',reason:'The authenticated identity has an applicable allow and no explicit deny.'};return {decision:'Deny',reason:'No applicable allow: implicit deny.'};}
function revenue(rows,region){if(!Array.isArray(rows))throw Error('Rows required.');return rows.filter(r=>region==='all'||r.region===region).reduce((sum,r)=>{if(!Number.isFinite(r.quantity)||!Number.isFinite(r.price))throw Error('Invalid numeric data.');return sum+r.quantity*r.price;},0);}
function longestPrefixMatch(ip,routes){const target=ipToNumber(ip);if(!Array.isArray(routes))throw Error('A route table is required.');let chosen=null;for(const route of routes){if(!route||!Number.isInteger(route.prefix)||route.prefix<0||route.prefix>32)throw Error('Route prefixes must be /0 through /32.');const network=ipToNumber(route.network),size=2**(32-route.prefix);if(network%size!==0)throw Error('Route network must be aligned to its prefix.');if(Math.floor(target/size)*size===network&&(!chosen||route.prefix>chosen.prefix))chosen={...route};}return chosen;}
root.AthenaCore={matchesSearch,fresh,validateProgress,grade,subnet,longestPrefixMatch,policy,revenue,numberToIp,ipToNumber};if(typeof module!=='undefined'&&module.exports)module.exports=root.AthenaCore;
})(typeof globalThis!=='undefined'?globalThis:this);
